mapper.select:
select id, corpid, supplier_id, writeoff_no, payment_id, payable_id, writeoff_date, amount, status,
    reversed_time, remark, creator_id, modify_id
from payment_writeoff
where corpid = #{corpid}
  and id = #{id}
  and del = 0

mapper.update:
update payment_writeoff
set status = 0,
    reversed_time = #{reversedTime},
    modify_id = #{userId},
    update_time = #{reversedTime}
where corpid = #{corpid}
  and id = #{id}
  and del = 0
  and status = 1
